namespace sarif.export.extlib;





using com.google.gson;

using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifClassesNamespaceWriter : AbstractExtWriter {

	private List<GhidraClass> classes = new();
	private ExternalManager externalManager;
	private SymbolTable symbolTable;

	public SarifClassesNamespaceWriter(ExternalManager externalManager, SymbolTable symbolTable,
			List<GhidraClass> request, Writer baseWriter)
    : base(baseWriter)
    {
		this.externalManager = externalManager;
		this.symbolTable = symbolTable;
		this.classes = request;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genClasses(monitor);
		root.add("definedData", objects);
	}

	private void genClasses(TaskMonitor monitor)
    {
		monitor.initialize(classes.size());
		Iterator<GhidraClass> classNamespaces = symbolTable.getClassNamespaces();
		while (classNamespaces.hasNext()) {
			monitor.checkCancelled();
			GhidraClass next = classNamespaces.next();
			walkSymbols(next);
			monitor.increment();
		}
	}

	private void walkSymbols(GhidraClass cls) {
		string clsName = cls.getName(true);
		string path = externalManager.getExternalLibraryPath(clsName);
		if (path == null) {
			path = "";
		}
		ExtLibrary lib = new ExtLibrary(clsName, path, SourceType.DEFAULT);
		SarifObject sarif = new SarifObject(ExternalLibSarifMgr.SUBKEY0, ExternalLibSarifMgr.KEY,
			getTree(lib), null);
		objects.add(getTree(sarif));

		if (cls.isExternal()) {
			SymbolIterator symbols = symbolTable.getSymbols(cls);
			while (symbols.hasNext()) {
				Symbol sym = symbols.next();
				ExternalLocation loc = externalManager.getExternalLocation(sym);
				if (loc != null) {
					ExtLibraryLocation obj = new ExtLibraryLocation(loc);
					SarifObject sarif2 = new SarifObject(ExternalLibSarifMgr.SUBKEY1,
						ExternalLibSarifMgr.KEY, getTree(obj), loc.getAddress(), loc.getAddress());
					objects.add(getTree(sarif2));
				}
			}
		}
	}

	/* @Override */
	public JsonArray getResults() {
		return objects;
	}

}
